-- READ-ONLY exact epoch LuhaMet availability for the full 2014 source-retained RH target-null cohort. No nearest-time fallback.
WITH c AS (SELECT o.dateTime,o.outHumidity source_rh,o.outTemp source_temp FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime JOIN `pocasi-loucka.eu_old`.archive eo ON eo.dateTime=o.dateTime JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime WHERE o.dateTime>=1388534400 AND o.dateTime<1420070400 AND r.outHumidity IS NULL AND o.outHumidity IS NOT NULL AND o.outHumidity=w.outHumidity AND o.outHumidity=eo.outHumidity AND NOT EXISTS(SELECT 1 FROM loucka_reconstruction.reconstruction_changes x WHERE x.target_time=o.dateTime AND x.variable='outHumidity')) SELECT c.source_rh,COUNT(*) candidate_rows,SUM(l.relative_humidity_pct IS NOT NULL) exact_luhamet_rh,SUM(c.source_temp IS NOT NULL) source_temp_present FROM c LEFT JOIN loucka_reconstruction.reference_observations l ON l.station_id='luhamet_sehradice' AND l.observed_at_utc=c.dateTime GROUP BY c.source_rh ORDER BY candidate_rows DESC;
